// Optional build dependency only: wabt (or OET_WABT_PATH). The runtime ships
// only generated bytes. f64 operation order matches the reference JS tape;
// no fast-math reassociation, finite differences or Hessian approximation.
import fs from 'node:fs/promises';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url),g=n=>`(local.get $${n})`,set=(n,v)=>`(local.set $${n} ${v})`,i=v=>`(i32.const ${v})`,f=v=>`(f64.const ${v})`,
    op=(name,...args)=>`(${name} ${args.join(' ')})`,ia=(a,b)=>op('i32.add',a,b),im=(a,b)=>op('i32.mul',a,b),is=(a,b)=>op('i32.sub',a,b),
    fa=(a,b)=>op('f64.add',a,b),fm=(a,b)=>op('f64.mul',a,b),
    load=(base,index)=>op('f64.load',ia(g(base),im(index,i(8)))),store=(base,index,value)=>op('f64.store',ia(g(base),im(index,i(8))),value),
    li=(base,index)=>op('i32.load',ia(g(base),im(index,i(4)))),
    finite=value=>op('f64.lt',op('f64.abs',value),f('inf')),
    choose=(condition,yes,no='')=>`(if ${condition} (then ${yes})${no?` (else ${no})`:''})`;
let serial=0;
const loop=(name,start,condition,next,body)=>{const id=serial++;return `${set(name,start)} (block $done${id} (loop $loop${id}
 (br_if $done${id} (i32.eqz ${condition})) ${body} ${set(name,next)} (br $loop${id})))`;};
const parameters=names=>names.map(n=>`(param $${n} i32)`).join(' '),locals=(names,type)=>names.map(n=>`(local $${n} ${type})`).join(' '),
    increment=(base,index,value)=>store(base,index,fa(load(base,index),value)),
    checkedGradient=value=>`${set('value',value)} ${choose(op('i32.eqz',finite(g('value'))),'(return (i32.const 1))')} ${store('data',ia(g('at'),g('j')),g('value'))}`;
const forward=`(func (export "forward") ${parameters(['data','coeff','pa','pb','variable','D','begin','end'])} (result i32)
 ${locals(['node','at','a','b','c','j','index','stride'],'i32')} ${locals(['da','db','value'],'f64')}
 ${set('stride',ia(g('D'),i(1)))}
 ${loop('node',g('begin'),op('i32.lt_s',g('node'),g('end')),ia(g('node'),i(1)),`
   ${set('at',im(g('node'),g('stride')))}
   ${choose(op('i32.eqz',finite(load('data',g('at')))),'(return (i32.const 1))')}
   ${set('a',li('pa',g('node')))} ${set('b',li('pb',g('node')))} ${set('c',im(g('node'),i(5)))}
   ${choose(op('i32.lt_s',g('a'),i(0)),`
     (memory.fill ${ia(g('data'),im(ia(g('at'),i(1)),i(8)))} (i32.const 0) ${im(g('D'),i(8))})
     ${set('index',li('variable',g('node')))}
     ${choose(op('i32.ge_s',g('index'),i(0)),store('data',ia(ia(g('at'),i(1)),g('index')),f(1)))}`,`
     ${set('da',load('coeff',g('c')))} ${set('db',load('coeff',ia(g('c'),i(1))))}
     ${choose(op('i32.lt_s',g('b'),i(0)),
       loop('j',i(1),op('i32.le_s',g('j'),g('D')),ia(g('j'),i(1)),checkedGradient(fm(g('da'),load('data',ia(g('a'),g('j')))))),
       loop('j',i(1),op('i32.le_s',g('j'),g('D')),ia(g('j'),i(1)),checkedGradient(fa(fm(g('da'),load('data',ia(g('a'),g('j')))),fm(g('db'),load('data',ia(g('b'),g('j'))))))))}`)}
 `)} (i32.const 0))`;

const aj=ia(g('a'),g('j')),bj=ia(g('b'),g('j')),atj=ia(g('at'),g('j')),
    directions=body=>loop('j',i(1),op('i32.le_s',g('j'),g('D')),ia(g('j'),i(1)),body),
    linearA=fm(g('da'),g('direction')),linearB=fm(g('db'),g('direction'));
const reverse=`(func (export "reverse") ${parameters(['data','adj','coeff','pa','pb','variable','active','D','end','output','result'])} (result i32)
 ${locals(['node','at','a','b','c','j','index','stride','out'],'i32')} ${locals(['da','db','daa','dab','dbb','bar','direction','ga','gb','value'],'f64')}
 ${set('stride',ia(g('D'),i(1)))}
 (memory.fill ${g('adj')} (i32.const 0) ${im(im(g('end'),g('stride')),i(8))})
 (memory.fill ${g('active')} (i32.const 0) ${g('end')})
 (memory.fill ${g('result')} (i32.const 0) ${im(im(g('D'),g('D')),i(8))})
 ${store('adj',g('output'),f(1))}
 (i32.store8 ${ia(g('active'),op('i32.div_u',g('output'),g('stride')))} (i32.const 1))
 ${loop('node',is(g('end'),i(1)),op('i32.ge_s',g('node'),i(0)),is(g('node'),i(1)),`
 ${choose(op('i32.load8_u',ia(g('active'),g('node'))),`
   ${set('a',li('pa',g('node')))} ${set('b',li('pb',g('node')))}
   ${choose(op('i32.ge_s',g('a'),i(0)),`
     ${set('at',im(g('node'),g('stride')))} ${set('c',im(g('node'),i(5)))}
     ${['da','db','daa','dab','dbb'].map((name,j)=>set(name,load('coeff',ia(g('c'),i(j))))).join('\n')}
     ${set('bar',load('adj',g('at')))}
     (i32.store8 ${ia(g('active'),op('i32.div_u',g('a'),g('stride')))} (i32.const 1))
     ${increment('adj',g('a'),fm(g('da'),g('bar')))}
     ${choose(op('i32.lt_s',g('b'),i(0)),`
       ${choose(op('f64.eq',g('daa'),f(0)),
         directions(increment('adj',aj,fm(g('da'),load('adj',atj)))),
         directions(increment('adj',aj,fa(fm(g('da'),load('adj',atj)),fm(fm(g('bar'),g('daa')),load('data',aj))))))}
     `,`
       (i32.store8 ${ia(g('active'),op('i32.div_u',g('b'),g('stride')))} (i32.const 1))
       ${increment('adj',g('b'),fm(g('db'),g('bar')))}
       ${choose(op('i32.and',op('i32.and',op('f64.eq',g('daa'),f(0)),op('f64.eq',g('dab'),f(0))),op('f64.eq',g('dbb'),f(0))),
          directions(`${set('direction',load('adj',atj))} ${increment('adj',aj,linearA)} ${increment('adj',bj,linearB)}`),
          choose(op('i32.and',op('i32.and',op('f64.eq',g('daa'),f(0)),op('f64.eq',g('dab'),f(1))),op('f64.eq',g('dbb'),f(0))),
            directions(`${set('direction',load('adj',atj))} ${increment('adj',aj,fa(linearA,fm(g('bar'),load('data',bj))))} ${increment('adj',bj,fa(linearB,fm(g('bar'),load('data',aj))))}`),
            directions(`${set('direction',load('adj',atj))} ${set('ga',load('data',aj))} ${set('gb',load('data',bj))}
              ${increment('adj',aj,fa(linearA,fm(g('bar'),fa(fm(g('daa'),g('ga')),fm(g('dab'),g('gb'))))))}
              ${increment('adj',bj,fa(linearB,fm(g('bar'),fa(fm(g('dab'),g('ga')),fm(g('dbb'),g('gb'))))))}`)))}
     `)}
   `)}
 `)}
 `)}
 ${loop('node',i(0),op('i32.lt_s',g('node'),g('end')),ia(g('node'),i(1)),`
   ${set('index',li('variable',g('node')))}
   ${choose(op('i32.ge_s',g('index'),i(0)),`
     ${set('out',im(g('index'),g('D')))} ${set('at',im(g('node'),g('stride')))}
     ${loop('j',i(0),op('i32.lt_s',g('j'),g('D')),ia(g('j'),i(1)),`
       ${set('value',fa(load('result',ia(g('out'),g('j'))),load('adj',ia(ia(g('at'),i(1)),g('j')))))}
       ${choose(op('i32.eqz',finite(g('value'))),'(return (i32.const 1))')}
       ${store('result',ia(g('out'),g('j')),g('value'))}
     `)}
   `)}
 `)} (i32.const 0))`;
const wat=`(module (import "env" "memory" (memory 1)) ${forward} ${reverse})`,wabt=await require(process.env.OET_WABT_PATH||'wabt')(),
    parsed=wabt.parseWat('compositeStrainKernel.wat',wat,{bulk_memory:true});
parsed.resolveNames();parsed.validate();const {buffer}=parsed.toBinary({log:false,write_debug_names:false});
await fs.writeFile(new URL('../../src/physics/kirchhoffCompositeStrainKernelBytes.js',import.meta.url),
    `// Generated by scripts/physics/build-composite-strain-kernel.mjs. Do not edit.\nexport const compositeStrainKernelBytes=new Uint8Array([${Array.from(buffer)}]);\n`);
console.log(JSON.stringify({bytes:buffer.length,scope:'exact batched first derivatives and reverse-adjoint derivatives'}));
